'use client';

import React, { useState } from 'react';
import * as XLSX from 'xlsx';
import { Sidebar } from '../components/Sidebar';
import { useLanguage } from '../contexts/LanguageContext';
import { apiRequest } from '../contexts/AuthContext';

type ImportField =
  | 'name'
  | 'nameAr'
  | 'brand'
  | 'sku'
  | 'barcode'
  | 'qrCode'
  | 'buyPrice'
  | 'sellPrice'
  | 'stockQuantity'
  | 'minStockLevel';

type ImportReport = {
  importedCount: number;
  skipped: Array<{ row: number; reason: string }>;
  warnings: string[];
};

const fieldMatchers: Record<ImportField, string[]> = {
  name: ['name', 'product', 'item', 'description', 'title', 'productname'],
  nameAr: ['name_ar', 'name ar', 'arabic', 'arabicname', 'اسم', 'الوصف'],
  brand: ['brand', 'manufacturer', 'company', 'mark', 'الماركة', 'العلامة'],
  sku: ['sku', 'itemcode', 'code', 'partnumber', 'part', 'reference', 'ref'],
  barcode: ['barcode', 'bar code', 'ean', 'upc', 'gtin', 'باركود'],
  qrCode: ['qr', 'qrcode', 'qr code'],
  buyPrice: ['buy', 'cost', 'purchase', 'buyprice', 'costprice', 'purchaseprice', 'تكلفة', 'سعر الشراء'],
  sellPrice: ['sell', 'price', 'sale', 'sellprice', 'saleprice', 'unitprice', 'السعر', 'سعر البيع'],
  stockQuantity: ['qty', 'quantity', 'stock', 'available', 'onhand', 'كمية', 'المخزون'],
  minStockLevel: ['min', 'minimum', 'reorder', 'minstock', 'min stock', 'حد ادنى', 'حد أدنى'],
};

const normalizeHeader = (value: string) =>
  value
    .toString()
    .trim()
    .toLowerCase()
    .replace(/[_\-]/g, ' ')
    .replace(/\s+/g, ' ');

const detectFields = (headers: string[]) => {
  const map: Record<number, ImportField> = {};
  const unmatched: string[] = [];
  headers.forEach((header, index) => {
    const normalized = normalizeHeader(header);
    const match = (Object.keys(fieldMatchers) as ImportField[]).find((field) =>
      fieldMatchers[field].some((key) => normalized.includes(normalizeHeader(key)))
    );
    if (match) {
      map[index] = match;
    } else if (normalized) {
      unmatched.push(header);
    }
  });

  return { map, unmatched };
};

const inferFields = (rows: string[][]) => {
  const sample = rows.slice(0, 10);
  const columnCount = Math.max(...sample.map((row) => row.length));
  const stats = Array.from({ length: columnCount }, () => ({
    textCount: 0,
    numericCount: 0,
    integerCount: 0,
    total: 0,
    avg: 0,
    barcodeCount: 0,
  }));

  sample.forEach((row) => {
    row.forEach((cell, index) => {
      const value = cell?.toString().trim();
      if (!value) return;
      stats[index].total += 1;
      const numeric = Number(value.replace(/,/g, ''));
      const isNumeric = !Number.isNaN(numeric);
      if (isNumeric) {
        stats[index].numericCount += 1;
        stats[index].avg += numeric;
        if (Number.isInteger(numeric)) stats[index].integerCount += 1;
        if (/^\d{8,15}$/.test(value)) stats[index].barcodeCount += 1;
      } else {
        stats[index].textCount += 1;
      }
    });
  });

  stats.forEach((stat) => {
    if (stat.numericCount) stat.avg = stat.avg / stat.numericCount;
  });

  const map: Record<number, ImportField> = {};
  const nameIndex = stats
    .map((stat, index) => ({ index, score: stat.textCount }))
    .sort((a, b) => b.score - a.score)[0]?.index;

  if (nameIndex !== undefined) {
    map[nameIndex] = 'name';
  }

  const barcodeIndex = stats
    .map((stat, index) => ({ index, score: stat.barcodeCount }))
    .sort((a, b) => b.score - a.score)[0]?.index;

  if (barcodeIndex !== undefined && stats[barcodeIndex].barcodeCount > 0) {
    map[barcodeIndex] = 'barcode';
  }

  const numericColumns = stats
    .map((stat, index) => ({ index, avg: stat.avg, numeric: stat.numericCount }))
    .filter((stat) => stat.numeric > 0 && (!map[stat.index] || map[stat.index] !== 'barcode'))
    .sort((a, b) => b.avg - a.avg);

  if (numericColumns[0]) {
    map[numericColumns[0].index] = 'sellPrice';
  }
  if (numericColumns[1]) {
    map[numericColumns[1].index] = 'buyPrice';
  }

  const quantityColumn = stats
    .map((stat, index) => ({ index, score: stat.integerCount, avg: stat.avg }))
    .filter((stat) => stat.score > 0 && !map[stat.index])
    .sort((a, b) => a.avg - b.avg)[0];

  if (quantityColumn) {
    map[quantityColumn.index] = 'stockQuantity';
  }

  return map;
};

export default function ExcelImportPage() {
  const { t, direction, language } = useLanguage();
  const [report, setReport] = useState<ImportReport | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleFile = async (file: File) => {
    setError(null);
    setReport(null);
    setLoading(true);

    try {
      const data = await file.arrayBuffer();
      const workbook = XLSX.read(data, { type: 'array' });
      const sheetName = workbook.SheetNames[0];
      const sheet = workbook.Sheets[sheetName];
      const rows = XLSX.utils.sheet_to_json<string[]>(sheet, { header: 1, raw: false });
      if (rows.length < 2) {
        throw new Error('No data rows found');
      }

      const headers = rows[0].map((h) => (h ? h.toString() : ''));
      let { map, unmatched } = detectFields(headers);
      if (Object.keys(map).length === 0) {
        map = inferFields(rows.slice(1));
        unmatched = [];
      }

      const items: any[] = [];
      const skipped: Array<{ row: number; reason: string }> = [];

      rows.slice(1).forEach((row, rowIndex) => {
        const rowData: any = {};
        Object.entries(map).forEach(([index, field]) => {
          const cell = row[Number(index)];
          if (cell !== undefined && cell !== null && cell !== '') {
            rowData[field] = cell;
          }
        });

        if (!rowData.name && !rowData.nameAr) {
          skipped.push({ row: rowIndex + 2, reason: 'Missing product name' });
          return;
        }

        items.push({
          name: rowData.name || rowData.nameAr,
          nameAr: rowData.nameAr,
          brand: rowData.brand,
          sku: rowData.sku,
          barcode: rowData.barcode,
          qrCode: rowData.qrCode,
          buyPrice: rowData.buyPrice,
          sellPrice: rowData.sellPrice,
          stockQuantity: rowData.stockQuantity,
          minStockLevel: rowData.minStockLevel,
        });
      });

      if (items.length === 0) {
        throw new Error('No recognizable product rows found');
      }

      const result = await apiRequest('/products/import', {
        method: 'POST',
        body: JSON.stringify({ items }),
      });

      const warnings = unmatched.length
        ? [
            language === 'ar'
              ? `أعمدة غير معروفة تم تخطيها: ${unmatched.join(', ')}`
              : `Unrecognized columns skipped: ${unmatched.join(', ')}`,
          ]
        : [];

      setReport({
        importedCount: result.importedCount || 0,
        skipped: [...skipped, ...(result.skipped || [])],
        warnings,
      });
    } catch (err: any) {
      setError(err.message || 'Failed to import file');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-black text-white flex" dir={direction}>
      <Sidebar />
      <div className="flex-1 p-8 overflow-y-auto">
        <h1 className="text-2xl font-bold text-cyan-200 mb-6">{t('excel.title')}</h1>
        <div className="neon-card rounded-xl p-6">
          <div className="border border-cyan-500/30 rounded-xl p-8 text-center">
            <div className="text-slate-300 mb-4">Excel</div>
            <input
              type="file"
              accept=".xlsx,.xls,.csv"
              onChange={(e) => {
                const file = e.target.files?.[0];
                if (file) handleFile(file);
              }}
              className="block mx-auto text-sm text-slate-300 file:mr-4 file:rounded-lg file:border-0 file:bg-cyan-600 file:px-4 file:py-2 file:text-white file:font-semibold"
            />
          </div>
          {loading && <div className="mt-4 text-sm text-slate-300">{t('common.loading')}</div>}
          {error && (
            <div className="mt-4 rounded-lg border border-red-500/40 bg-red-500/10 p-3 text-sm text-red-200">
              {error}
            </div>
          )}
          {report && (
            <div className="mt-6 space-y-3 text-sm">
              <div className="text-green-300">
                {language === 'ar'
                  ? `تم استيراد ${report.importedCount} منتج`
                  : `Imported ${report.importedCount} products`}
              </div>
              {report.warnings.map((warning, idx) => (
                <div key={idx} className="text-yellow-300">
                  {warning}
                </div>
              ))}
              {report.skipped.length > 0 && (
                <div className="text-slate-300">
                  {language === 'ar' ? 'تم تخطي الصفوف:' : 'Skipped rows:'}
                  <ul className="mt-2 space-y-1">
                    {report.skipped.slice(0, 10).map((row) => (
                      <li key={`${row.row}-${row.reason}`}>
                        #{row.row}: {row.reason}
                      </li>
                    ))}
                    {report.skipped.length > 10 && (
                      <li>{language === 'ar' ? '...' : '...'}</li>
                    )}
                  </ul>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

